#!/bin/sh
# Xcode Cloud post-clone: bump CFBundleVersion only.
# Supabase URL + publishable key live in committed Loam/Config/Config.xcconfig.
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
REPO_ROOT="${CI_PRIMARY_REPOSITORY_PATH:-$(cd "$SCRIPT_DIR/.." && pwd)}"
SECRETS_FILE="${REPO_ROOT}/Loam/Config/Secrets.xcconfig"

mkdir -p "$(dirname "$SECRETS_FILE")"

if [ -z "${CI_BUILD_NUMBER:-}" ]; then
  echo "CI_BUILD_NUMBER unset — skipping Secrets.xcconfig (local CURRENT_PROJECT_VERSION stays at project default)."
  exit 0
fi

cat > "$SECRETS_FILE" <<EOF
// Generated by ci_post_clone.sh for Xcode Cloud build numbering.
CURRENT_PROJECT_VERSION = ${CI_BUILD_NUMBER}
EOF

echo "Wrote ${SECRETS_FILE} with CURRENT_PROJECT_VERSION=${CI_BUILD_NUMBER}."
